    border: 1px solid #4a89a9;
    position: sticky;
    left: 0;
    right: 0;
}

.popup {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) scale(0.95);
    background-color: #ccc;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.3);
    z-index: 2147483647;
    width: 80%;
    max-height: 80vh;
    overflow: auto;
    font-family: system-ui, -apple-system, sans-serif;
    opacity: 0;
    transition: all 0.3s ease;
    pointer-events: auto;
}

.titleElement {
    margin: 0 0 16px 0;
    color: #333;
    font-size: 18px;
    font-weight: 600;
}

.contentElement {
    white-space: pre-wrap;
    word-wrap: break-word;
    overflow-wrap: break-word;
    max-height: calc(80vh - 150px);
    overflow-y: auto;
    padding: 16px;
    background-color: #bbb;
    color: #000;
    border-radius: 6px;
    margin-bottom: 20px;
    font-size: 14px;
    line-height: 1.6;
    border: 1px solid #999;
}

